(function () {
  var S = window.METIN_TAHLILI_SAYFA, K = window.KITAP, H = window.HTML_SAYFALAR;
  if (!S || !S.length || !K || !H) return;
  var BAS = 5, ADET = S.length;                  /* basili 4. sayfadan sonra */

  /* Basili 5. sayfadan sonrasi ADET kadar ileri kayar (buyukten kucuge). */
  Object.keys(H).map(Number).filter(function (n) { return n >= BAS; })
    .sort(function (a, b) { return b - a; })
    .forEach(function (n) { H[n + ADET] = H[n]; delete H[n]; });
  S.forEach(function (sf, i) { sf.sayfa = BAS + i; H[BAS + i] = sf.html; });

  window.KIDEF_EK = {
    bas: BAS, adet: ADET, toplam: K.toplamSayfa + ADET,
    f: function (b) { return b >= BAS ? b + ADET : b; },
    b: function (f) { return f < BAS ? f : (f < BAS + ADET ? 0 : f - ADET); },
    etiket: function (f) { var x = S[f - BAS]; return x ? 'M' + x.sinif : ''; },
    ad: function (f) { var x = S[f - BAS]; return x ? 'Metin Tahlili · ' + x.kisa : ''; }
  };

  /* Basili ICINDEKILER sayfasi (s.4): sutunlarin altina serit. */
  var dugum = '</div></div><p class="i-ipucu">';
  if (H[4] && H[4].indexOf(dugum) >= 0) {
    var cips = S.map(function (sf) {
      return '<a class="i-mt-c" href="#mt' + sf.sinif + '" data-gitf="' + sf.sayfa
        + '">' + sf.kisa + '</a>';
    }).join('');
    H[4] = H[4].replace(dugum, '</div></div>'
      + '<div class="i-mt"><div class="i-mt-bas">'
      + '<svg class="i-mt-sim" viewBox="0 0 24 24" fill="none" stroke="currentColor"'
      + ' stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'
      + '<path d="M12 7C10 5.5 7.6 5 5 5.2v12C7.6 17 10 17.5 12 19"/>'
      + '<path d="M12 7c2-1.5 4.4-2 7-1.8v12c-2.6-.2-5 .3-7 1.8"/>'
      + '<path d="M12 7v12"/></svg> METIN TAHLILI '
      + '— 5-10. SINIF KITAPLARININ METINLERI (hemen sonraki sayfalar)</div>'
      + '<div class="i-mt-cips">' + cips + '</div></div>'
      + '<p class="i-ipucu">');
  }
})();
